package org.drk.hellojasper2026;import net.sf.jasperreports.engine.JasperExportManager;import net.sf.jasperreports.engine.JasperFillManager;import net.sf.jasperreports.engine.JasperPrint;import net.sf.jasperreports.view.JasperViewer;import java.util.HashMap;public class ReportService { public void showReport() {     var parametros = new HashMap<String,Object>(0);     var conn = ConnectionManager.getConnection();     String archivo = "informe.jasper";     try {     JasperPrint jasperPrint = JasperFillManager.fillReport(archivo, parametros, conn);     JasperViewer.viewReport(jasperPrint); } catch (Exception e) {     throw new RuntimeException(e); } }public void generatePDF(){     var parametros = new HashMap<String,Object>(0);     var conn = ConnectionManager.getConnection();     String archivo = "informe.jasper";     try {     JasperPrint jasperPrint = JasperFillManager.fillReport(archivo, parametros, conn);     JasperExportManager.exportReportToPdfFile(jasperPrint, "informe.pdf"); } catch (Exception e) {     throw new RuntimeException(e); } }}